package ginterp

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/build"
	"go/parser"
	"go/token"
	"io"
	"log"
	"os"
	"path/filepath"

	"github.com/james-lawrence/genieql"
	"github.com/james-lawrence/genieql/fsx"
	"github.com/james-lawrence/genieql/generators"
	"github.com/james-lawrence/genieql/internal/envx"
)

func WasiPackage() *build.Package {
	return &build.Package{
		Dir:           envx.String("", "GENIEQL_WASI_PACKAGE_DIR"),
		Name:          envx.String("", "GENIEQL_WASI_PACKAGE_NAME"),
		ImportComment: envx.String("", "GENIEQL_WASI_PACKAGE_IMPORT_COMMENT"),
		Doc:           envx.String("", "GENIEQL_WASI_PACKAGE_DOC"),
		ImportPath:    envx.String("", "GENIEQL_WASI_PACKAGE_IMPORT_PATH"),
		Root:          envx.String("", "GENIEQL_WASI_PACKAGE_ROOT"),
		SrcRoot:       envx.String("", "GENIEQL_WASI_PACKAGE_SRC_ROOT"),
		PkgRoot:       envx.String("", "GENIEQL_WASI_PACKAGE_PKG_ROOT"),
		PkgTargetRoot: envx.String("", "GENIEQL_WASI_PACKAGE_PKG_TARGET_ROOT"),
		BinDir:        envx.String("", "GENIEQL_WASI_PACKAGE_BIN_DIR"),
		Goroot:        envx.Boolean(false, "GENIEQL_WASI_PACKAGE_GO_ROOT"),
		PkgObj:        envx.String("", "GENIEQL_WASI_PACKAGE_PKG_OBJ"),
		AllTags:       envx.Strings(nil, "GENIEQL_WASI_PACKAGE_ALL_TAGS"),
		ConflictDir:   envx.String("", "GENIEQL_WASI_PACKAGE_CONFLICT_DIR"),
		BinaryOnly:    envx.Boolean(false, "GENIEQL_WASI_PACKAGE_BINARY_ONLY"),
		GoFiles:       envx.Strings(nil, "GENIEQL_WASI_PACKAGE_GO_FILES"),
	}
}

// LoadFiles parses the source files provided by the host into a shared file set,
// keyed by file name.
func LoadFiles() (trees map[string]*ast.File, fset *token.FileSet, err error) {
	var (
		paths = envx.Strings(nil, "GENIEQL_WASI_FILEPATH")
	)

	trees = make(map[string]*ast.File, len(paths))
	fset = token.NewFileSet()

	if envx.Boolean(true, "GENIEQL_WASI_DEBUG") {
		log.Println("LOADING FILES", paths)
		fsx.PrintString(filepath.Join(filepath.Dir(paths[0]), "src", "main.go"))
		for _, fp := range paths {
			fsx.PrintString(fp)
		}
	}

	for _, fp := range paths {
		if trees[filepath.Base(fp)], err = parser.ParseFile(fset, fp, nil, parser.ParseComments); err != nil {
			return nil, nil, err
		}
	}

	return trees, fset, nil
}

// Scratch accumulates the code generated during a run, mirroring it to stdout
// for the host and publishing it to the package searcher so later phases
// resolve declarations produced by earlier ones.
type Scratch struct {
	ctx generators.Context
	buf bytes.Buffer
}

func NewScratch(ctx generators.Context) *Scratch {
	return &Scratch{ctx: ctx}
}

// Generate runs the generator, writing its output to stdout and the scratch.
func (t *Scratch) Generate(gen genieql.Generator) (err error) {
	var (
		dst = io.MultiWriter(os.Stdout, &t.buf)
	)

	if err = gen.Generate(dst); err != nil {
		return err
	}

	_, err = fmt.Fprintln(dst)

	return err
}

// Publish makes the code generated so far visible to searches of the package.
func (t *Scratch) Publish() error {
	return genieql.NewUtils(t.ctx.FileSet).AddFile(
		t.ctx.CurrentPackage,
		"genieql.scratch.go",
		fmt.Sprintf("package %s\n%s", t.ctx.CurrentPackage.Name, t.buf.String()),
	)
}

// Const resolves a string constant declared by the package, including constants
// generated by an earlier phase.
func Const(ctx generators.Context, name string) (_ string, err error) {
	var (
		pkgs []*ast.Package
	)

	if pkgs, err = genieql.NewUtils(ctx.FileSet).ParsePackages(ctx.CurrentPackage); err != nil {
		return "", err
	}

	return genieql.RetrieveBasicLiteralString(genieql.FilterName(name), pkgs...)
}
